def minDays(bloomDay, m, k):
    n = len(bloomDay)
    if m * k > n:
        return -1
    left, right = min(bloomDay), max(bloomDay)
    def canMake(day):
        bouquets = flowers = 0
        for d in bloomDay:
            if d <= day:
                flowers += 1
                if flowers == k:
                    bouquets += 1
                    flowers = 0
            else:
                flowers = 0
        return bouquets >= m
    while left < right:
        mid = (left + right) // 2
        if canMake(mid):
            right = mid
        else:
            left = mid + 1
    return left
